}

What will be the output of the following JavaScript code?

var B = 65;
var grade = B;
var result = 0;
switch (grade) {
  case 'A':
    result += 10;
    break;
  case 'B':
    result += 9;
    break;
  case 'C':
    result += 8;
    break;
  default:
    result += 0;
}
document.write(result);

What will be the output of the following JavaScript code?

var grade = 'A';
var result = 0;
switch (grade) {
  case 'A':
    result += 10;
  case 'B':
    result += 9;
  case 'C':
    result += 8;
  default:
    result += 0;
}
document.write(result);

What will be the output of the following JavaScript code?

var a = 4;
var b = 1;
var c = 0;
if (a === b)
  document.write(a);
else if (a === c)
  document.write(a);
else
  document.write(c);

What will be the output of the following JavaScript code?

var grade = 'C';
var result = '';
switch (grade) {
  case 'A':
    result += ' 10';
  case 'B':
    result += ' 9';
  case 'C':
    result += ' 8';
  default:
    result += ' 0';
}
document.write(result);

What will be the output of the following JavaScript code?

function printArray(a) {
  var len = a.length, i = 0;
  if (len == 0)
    console.log('Empty Array');
  else {
    do {
      console.log(a[i]);
    } while (++i < len);
  }
}

What will the following JavaScript code snippet do?

function tail(o) {
  for (; o.next; o = o.next);
  return o;
}

What will be the equivalent code of the following JavaScript code?

for (var p in o)
  console.log(o[p]);

